const raw = $input.first().json;
const body = raw.body || raw;
const data = body.data || body;

const vehicleId    = data.vehicleId || data.entityId || null;
const brand        = (data.brand  || '').toLowerCase().trim();
const model        = (data.model  || '').toLowerCase().trim();
const year         = parseInt(data.year)  || null;
const vehicleTitle = data.vehicle_title   || [data.brand, data.model, data.year].filter(Boolean).join(' ');
const vehicleSlug  = data.vehicle_slug    || null;
const vehicleType  = data.vehicle_type    || null;
const price        = data.price !== undefined ? Number(data.price) : null;

if (!vehicleId) throw new Error('vehicleId ausente en payload');

return [{ json: { vehicleId, brand, model, year, vehicleTitle, vehicleSlug, vehicleType, price } }];

// Merge data from previous node (extract) + supabase response
const extracted = $('Extraer datos del vehículo').first().json;
const dbRows    = $input.all();
const db        = Array.isArray(dbRows) && dbRows.length > 0 ? dbRows[0].json : {};

const vehicleId    = extracted.vehicleId;
const brand        = (db.brand_name  || extracted.brand  || '').toLowerCase().trim();
const model        = (db.model_name  || extracted.model  || '').toLowerCase().trim();
const year         = db.year         || extracted.year   || null;
const price        = db.price        !== undefined ? Number(db.price) : (extracted.price !== null ? Number(extracted.price) : null);
const vehicleType  = db.vehicle_type || extracted.vehicleType || 'car';
const vehicleSlug  = db.slug         || extracted.vehicleSlug || null;
const vehicleTitle = extracted.vehicleTitle || [db.brand_name, db.model_name, db.year].filter(Boolean).join(' ');

return [{ json: { vehicleId, brand, model, year, price, vehicleType, vehicleSlug, vehicleTitle } }];

const vehicle = $('Combinar datos del vehículo').first().json;
const alerts  = $input.all().map(i => i.json);

function parsePrice(val) {
  if (!val) return null;
  // Handle Spanish format: 150.000 or 150000 or '150000€'
  return parseInt(String(val).replace(/[.\s]/g, '').replace(/[^0-9]/g, ''), 10) || null;
}

const matched = alerts.filter(a => {
  // vehicle_type: 'any' matches all, otherwise must match
  if (a.vehicle_type && a.vehicle_type !== 'any' && a.vehicle_type !== vehicle.vehicleType) return false;
  // brand: must match (case-insensitive) if set
  if (a.brand && a.brand.toLowerCase().trim() !== vehicle.brand) return false;
  // model: must match if set
  if (a.model && a.model.toLowerCase().trim() !== vehicle.model) return false;
  // budget_max: vehicle price must be <= budget
  if (a.budget_max && vehicle.price !== null) {
    const maxBudget = parsePrice(a.budget_max);
    if (maxBudget && vehicle.price > maxBudget) return false;
  }
  // year_min: vehicle year must be >= year_min
  if (a.year_min && vehicle.year !== null && vehicle.year < a.year_min) return false;
  return true;
});

if (matched.length === 0) return [];

const MARKET_URL = process.env.MARKET_URL || 'https://blacklabelmarket.es';

return matched.map(a => ({
  json: {
    alertId:       a.id,
    email:         a.email,
    vehicleId:     vehicle.vehicleId,
    vehicleTitle:  vehicle.vehicleTitle,
    vehicleUrl:    vehicle.vehicleSlug ? `${MARKET_URL}/coches/${vehicle.vehicleSlug}` : MARKET_URL,
    price:         vehicle.price,
    brand:         vehicle.brand,
    model:         vehicle.model,
    year:          vehicle.year,
  }
}));

const d = $input.first().json;
const MAIL_FROM  = process.env.MAIL_FROM  || 'Black Label Market <no-reply@blacklabelmarket.es>';
const MARKET_URL = process.env.MARKET_URL || 'https://blacklabelmarket.es';

const priceText = d.price ? new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(d.price) : 'Consultar precio';

const html = `
<!DOCTYPE html>
<html lang="es">
<head><meta charset="UTF-8"><style>
  body { font-family: Arial, sans-serif; color: #1a1a1a; margin: 0; padding: 0; }
  .container { max-width: 580px; margin: 0 auto; padding: 32px 24px; }
  .header { color: #C6A64B; font-size: 22px; font-weight: 700; margin-bottom: 8px; }
  .subtitle { color: #555; font-size: 14px; margin-bottom: 24px; }
  .vehicle-card { background: #f8f8f8; border: 1px solid #e0e0e0; border-radius: 8px; padding: 20px; margin-bottom: 24px; }
  .vehicle-title { font-size: 18px; font-weight: 600; margin-bottom: 4px; }
  .vehicle-price { color: #C6A64B; font-size: 16px; font-weight: 700; margin-bottom: 16px; }
  .cta { display: inline-block; background: #C6A64B; color: #0B0B0B; text-decoration: none; padding: 12px 28px; border-radius: 4px; font-weight: 700; font-size: 15px; }
  .footer { margin-top: 32px; font-size: 12px; color: #888; }
</style></head>
<body>
<div class="container">
  <div class="header">¡Encontramos un vehículo para ti!</div>
  <div class="subtitle">Hemos encontrado un vehículo que coincide con tu alerta de búsqueda en Black Label Market.</div>
  <div class="vehicle-card">
    <div class="vehicle-title">${d.vehicleTitle}</div>
    <div class="vehicle-price">${priceText}</div>
    <a href="${d.vehicleUrl}" class="cta">Ver vehículo →</a>
  </div>
  <p>Si ya no te interesa esta búsqueda, puedes <a href="${MARKET_URL}/cuenta/alertas">gestionar tus alertas aquí</a>.</p>
  <div class="footer">Black Label Market · ${MARKET_URL}</div>
</div>
</body>
</html>`;

return [{
  json: {
    ...d,
    emailPayload: {
      from:    MAIL_FROM,
      to:      [d.email],
      subject: `¡Encontramos tu ${d.vehicleTitle}! - Black Label Market`,
      html
    }
  }
}];
